/* Journalit browser workspace: local-only starter implementation. */
const STORE_KEY='journalit-web-v1';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const money=(n,currency='USD')=>new Intl.NumberFormat('en-US',{style:'currency',currency,maximumFractionDigits:2}).format(Number(n)||0);
const dateFmt=(d,opts={month:'short',day:'numeric',year:'numeric'})=>new Intl.DateTimeFormat(undefined,opts).format(new Date(`${d}T12:00:00`));
const isoDay=(d)=>{const x=new Date(d);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`};
const esc=(s='')=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function makeSeed(){const symbols=['EURUSD','NQ','XAUUSD','ES','BTCUSD','GBPUSD','CL','AAPL'],setups=['Breakout','Pullback','Reversal','Opening Range'],accounts=['Apex Evaluation','Personal'],days=[];for(let i=35;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);if(d.getDay()===0||d.getDay()===6)continue;days.push(isoDay(d))}return days.map((date,i)=>{const pnl=Math.round((Math.sin(i*2.31)*.55+Math.cos(i*.81)*.35+(i%4===0?-.2:.14))*185*100)/100;return{id:`demo-${i}`,date,instrument:symbols[i%symbols.length],direction:i%3===0?'Short':'Long',setup:setups[i%setups.length],account:accounts[i%2],assetType:i%2?'Futures':'Forex',size:i%2?2:1,pnl,reviewed:i%4!==1,notes:'Planned entry, managed risk, and reviewed execution.',tags:i%3===0?['A setup']:['London']}})}
function loadState(){try{const x=JSON.parse(localStorage.getItem(STORE_KEY));if(x&&Array.isArray(x.trades))return{...x,setups:[...new Set([...(x.setups||[]),...x.trades.map(t=>t.setup).filter(Boolean)])],settings:{name:'Trader',goal:1000,currency:'USD',...x.settings}}}catch{}return{trades:makeSeed(),accounts:[{name:'Apex Evaluation',type:'Prop evaluation',balance:50000,currency:'USD',status:'Active'},{name:'Personal',type:'Personal',balance:12500,currency:'USD',status:'Active'}],setups:['Breakout','Pullback','Reversal','Opening Range'],settings:{name:'Trader',goal:1000,currency:'USD'},reviews:[]}}
let state=loadState(),page=location.hash.slice(1)||'home',filterText='',sessionInterval=null,sessionSeconds=25*60,activeGrowthAccount='';
const pageNames={home:'Home',trades:'Trade Log',dashboard:'Dashboard',accounts:'Accounts',setups:'Setups',reviews:'Reviews',calendar:'Calendar',session:'Session Mode',import:'Import trades',settings:'Settings & data'};
const num=(v)=>Number.isFinite(Number(v))?Number(v):0;const sum=(a)=>a.reduce((s,x)=>s+num(x.pnl),0);
function save(){localStorage.setItem(STORE_KEY,JSON.stringify(state));window.JournalitCloud?.schedule(()=>state,error=>toast(`Cloud save failed: ${error.message}`))}
function filteredTrades(){return state.trades.filter(t=>`${t.instrument} ${t.direction} ${t.setup} ${t.account} ${(t.tags||[]).join(' ')}`.toLowerCase().includes(filterText.toLowerCase()))}
function stats(ts=state.trades){const total=ts.length,wins=ts.filter(t=>num(t.pnl)>0),losses=ts.filter(t=>num(t.pnl)<0),grossWin=sum(wins),grossLoss=Math.abs(sum(losses));return{total,pnl:sum(ts),winRate:total?wins.length/total*100:0,avg:total?sum(ts)/total:0,profitFactor:grossLoss?grossWin/grossLoss:grossWin?grossWin:0,wins:wins.length,reviewed:ts.filter(t=>t.reviewed).length}}
function lineChart(ts=state.trades){const daily={};[...ts].sort((a,b)=>a.date.localeCompare(b.date)).forEach(t=>daily[t.date]=(daily[t.date]||0)+num(t.pnl));let vals=[0];Object.values(daily).forEach(v=>vals.push(vals.at(-1)+v));if(vals.length<2)vals=[0,0];const min=Math.min(0,...vals),max=Math.max(1,...vals),w=690,h=135,p=8;const pts=vals.map((v,i)=>`${p+i*(w-p*2)/(vals.length-1)},${h-p-(v-min)/(max-min)*(h-p*2)}`).join(' ');const y0=h-p-(0-min)/(max-min)*(h-p*2);return `<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><defs><linearGradient id="fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#39d17b" stop-opacity=".22"/><stop offset="1" stop-color="#39d17b" stop-opacity="0"/></linearGradient></defs><path d="M ${pts.replaceAll(' ',' L ')} L ${w-p} ${h} L ${p} ${h} Z" fill="url(#fill)"/><line x1="0" y1="${y0}" x2="${w}" y2="${y0}" stroke="#353b36" stroke-dasharray="4 5"/><polyline points="${pts}" fill="none" stroke="#39d17b" stroke-width="2.2" vector-effect="non-scaling-stroke" stroke-linecap="round" stroke-linejoin="round"/></svg>`}
function weeklyBars(){const today=new Date(),monday=new Date(today);monday.setDate(today.getDate()-((today.getDay()+6)%7));const ds=Array.from({length:5},(_,i)=>{const d=new Date(monday);d.setDate(d.getDate()+i);return isoDay(d)});const vals=ds.map(d=>sum(state.trades.filter(t=>t.date===d))),max=Math.max(1,...vals.map(Math.abs));return vals.map((v,i)=>`<div class="week-bar-col"><div class="week-bar ${v<0?'loss':''}" style="height:${Math.max(3,Math.abs(v)/max*52)}px"></div><span>${['M','T','W','T','F'][i]}</span></div>`).join('')}
function heatCells(){const d=new Date(),cells=[];for(let i=83;i>=0;i--){const x=new Date(d);x.setDate(d.getDate()-i);const day=isoDay(x),pnl=sum(state.trades.filter(t=>t.date===day));let cls='';if(pnl>250)cls='p3';else if(pnl>0)cls='p2';else if(pnl< -180)cls='l2';else if(pnl<0)cls='l1';else if(pnl>0)cls='p1';cells.push(`<i class="heatmap-cell ${cls}" title="${dateFmt(day)} · ${money(pnl)}"></i>`)}return cells.join('')}
function radar(){return `<svg class="radar" viewBox="0 0 160 130" aria-label="Trading score radar"><g fill="none" stroke="#39423b" stroke-width="1">${[1,.75,.5,.25].map((s)=>{const pts=Array.from({length:5},(_,i)=>{const a=-Math.PI/2+i*2*Math.PI/5;return `${80+60*s*Math.cos(a)},${63+56*s*Math.sin(a)}`}).join(' ');return `<polygon points="${pts}"/>`}).join('')}<path d="M80 7v112M23 45l114 37M44 113l72-99M23 82l114-37M44 13l72 100"/></g><polygon points="80,20 127,49 118,87 80,108 42,78" fill="#39d17b35" stroke="#39d17b" stroke-width="2"/></svg>`}
function recentList(){return [...state.trades].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6).map(t=>`<div class="recent-item" data-trade="${esc(t.id)}"><div><b>${esc(t.instrument)} · ${esc(t.direction)}</b><small>${dateFmt(t.date)} · ${esc(t.setup||'No setup')}</small></div><strong class="${t.pnl>=0?'positive':'negative'}">${money(t.pnl)}</strong></div>`).join('')||'<div class="empty-note">Add your first trade to begin.</div>'}
function dashboardHome(){const s=stats(),last7=state.trades.filter(t=>{const d=new Date();d.setDate(d.getDate()-6);return t.date>=isoDay(d)}),week=sum(last7),today=isoDay(new Date()),todayCount=state.trades.filter(t=>t.date===today).length,bySetup={};state.trades.forEach(t=>bySetup[t.setup||'Unassigned']=(bySetup[t.setup||'Unassigned']||0)+num(t.pnl));const best=Object.entries(bySetup).sort((a,b)=>b[1]-a[1])[0]||['No setup',0],equity=50000+s.pnl;return `<div class="page-heading"><div><h1>Good to see you, ${esc(state.settings.name)}</h1><p>Time to elevate your trading</p></div><div class="heading-actions"><button class="button" data-action="go" data-page="dashboard">▦ Dashboard</button><button class="button" data-action="add-trade">＋ Add trade</button></div></div><div class="grid home-grid">
<section class="card week-card"><div class="card-label">This week <span class="subtle">${last7.length} trades</span></div><div class="week-total"><div class="metric-big ${week>=0?'positive':'negative'}">${money(week)}</div><div class="metric-note">${week>=0?'above':'below'} your weekly average</div></div><div class="week-bars">${weeklyBars()}</div></section>
<section class="card heat-card"><div class="card-label">Last 12 weeks <span class="subtle">Profit / loss activity</span></div><div class="heatmap">${heatCells()}</div><div class="heat-legend">Less <i></i><i></i><i></i> More</div></section>
<section class="card streak-card"><div class="card-label">Streak <span class="subtle">current run</span></div><div class="streak-center"><div class="streak-icon">♨</div><div class="metric-big positive">${s.wins} <small style="font-size:12px">wins</small></div><div class="metric-note">${s.winRate.toFixed(0)}% win rate overall</div></div></section>
<section class="card review-card"><div class="card-label">Trades to review <span>›</span></div><div class="review-number">${s.total-s.reviewed}</div><div class="metric-note">${s.reviewed} reviewed · ${todayCount} today</div><div class="review-action" data-action="go" data-page="reviews">Open review queue <span>→</span></div></section>
<section class="card recent-card"><div class="card-label">Recent trades <button class="link-button" data-action="go" data-page="trades">View all →</button></div><div class="recent-list">${recentList()}</div></section>
<section class="card equity-card"><div class="card-label">Account equity <span class="subtle">All accounts</span></div><div class="chart-wrap">${lineChart()}</div><div style="display:flex;justify-content:space-between;align-items:end"><div><div class="metric-big">${money(equity)}</div><div class="metric-note">${state.accounts.length} accounts tracked</div></div><span class="positive" style="font-size:11px">↗ ${money(s.pnl)}</span></div></section>
<section class="card setup-card"><div class="card-label">Top setup <span class="subtle">by net P&amp;L</span></div><div class="account-name">${esc(best[0])}</div><div class="account-equity">${money(best[1])}</div><div class="metric-note">${state.trades.filter(t=>t.setup===best[0]).length} trades tagged</div><div style="margin-top:17px"><div class="progress"><i style="width:${Math.max(5,Math.min(100,s.winRate))}%"></i></div><small class="metric-note">${s.winRate.toFixed(0)}% win rate</small></div></section>
<section class="card account-widget"><div class="card-label">Accounts <button class="link-button" data-action="go" data-page="accounts">View all →</button></div><div class="account-name">${esc(state.accounts[0]?.name||'No accounts')}</div><div class="account-equity">${money((state.accounts[0]?.balance||0)+s.pnl)}</div><div class="account-lines"><span>Net P&amp;L</span><b class="${s.pnl>=0?'positive':'negative'}">${money(s.pnl)}</b></div><div class="account-lines"><span>Profit factor</span><b>${s.profitFactor.toFixed(2)}</b></div></section>
<section class="card score-card"><div class="card-label">Trading score <span class="subtle">Your journal performance</span></div><div class="score-layout">${radar()}<div class="score-number">${Math.round(s.winRate*.72+Math.min(28,s.reviewed/Math.max(1,s.total)*28))}<small>Building consistency</small></div>${radar()}</div></section>
<section class="card goal-card"><div class="card-label">Monthly goal <span class="subtle">P&amp;L target</span></div><div class="goal-number">${money(s.pnl)}</div><div class="metric-note" style="text-align:center">of ${money(state.settings.goal)} target</div><div class="goal-meter"><div class="progress"><i style="width:${Math.min(100,Math.max(3,s.pnl/state.settings.goal*100))}%"></i></div><small>${Math.round(Math.min(100,Math.max(0,s.pnl/state.settings.goal*100)))}% complete</small></div></section></div>`}
function tradeRows(ts){return ts.map(t=>`<tr data-trade="${esc(t.id)}"><td>${dateFmt(t.date,{month:'short',day:'numeric',year:'numeric'})}</td><td class="instrument">${esc(t.instrument)}</td><td><span class="pill">${esc(t.direction)}</span></td><td>${esc(t.setup||'—')}</td><td>${esc(t.account||'—')}</td><td>${num(t.size)}</td><td class="${t.pnl>=0?'positive':'negative'}">${money(t.pnl)}</td><td>${t.reviewed?'<span class="positive">✓ Reviewed</span>':'<span style="color:var(--yellow)">Needs review</span>'}</td><td><button class="icon-button" data-action="toggle-review" data-id="${esc(t.id)}" title="Toggle reviewed">${t.reviewed?'✓':'○'}</button></td></tr>`).join('')||`<tr><td colspan="9" class="empty-note">No trades found. Add a trade or import a CSV file.</td></tr>`}
function renderTrades(){const ts=filteredTrades(),s=stats(ts);return `<div class="page-heading"><div><h1>Trade Log</h1><p>Review every trade and find patterns in your execution.</p></div><div class="heading-actions"><button class="button" data-action="go" data-page="import">⇧ Import CSV</button><button class="button button-primary" data-action="add-trade">＋ Add trade</button></div></div><div class="stat-row"><div class="stat-box"><span>Net P&amp;L</span><b class="${s.pnl>=0?'positive':'negative'}">${money(s.pnl)}</b></div><div class="stat-box"><span>Total trades</span><b>${s.total}</b></div><div class="stat-box"><span>Win rate</span><b>${s.winRate.toFixed(1)}%</b></div><div class="stat-box"><span>Profit factor</span><b>${s.profitFactor.toFixed(2)}</b></div></div><section class="card table-card"><div class="table-toolbar"><h3>All trades <span class="subtle">${ts.length}</span></h3><div class="table-tools"><input class="filter-input" id="trade-search" placeholder="Filter trades…" value="${esc(filterText)}"><select class="select-control" id="review-filter"><option value="all">All trades</option><option value="unreviewed">Needs review</option><option value="reviewed">Reviewed</option></select></div></div><table class="trade-table"><thead><tr><th>Date</th><th>Instrument</th><th>Side</th><th>Setup</th><th>Account</th><th>Size</th><th>P&amp;L</th><th>Review</th><th></th></tr></thead><tbody>${tradeRows(ts)}</tbody></table></section>`}
function renderDashboard(){const s=stats();return `<div class="page-heading"><div><h1>Trading Dashboard</h1><p>Performance and patterns across ${s.total} recorded trades.</p></div><div class="heading-actions"><select class="select-control" id="period-filter"><option>All time</option><option>Last 30 days</option><option>This year</option></select></div></div><div class="stat-row"><div class="stat-box"><span>Net P&amp;L</span><b class="${s.pnl>=0?'positive':'negative'}">${money(s.pnl)}</b></div><div class="stat-box"><span>Win rate</span><b>${s.winRate.toFixed(1)}%</b></div><div class="stat-box"><span>Profit factor</span><b>${s.profitFactor.toFixed(2)}</b></div><div class="stat-box"><span>Average trade</span><b class="${s.avg>=0?'positive':'negative'}">${money(s.avg)}</b></div></div><div class="two-column"><section class="card"><div class="card-label">Cumulative P&amp;L <span class="subtle">By trade date</span></div><div class="large-chart">${lineChart()}</div></section><section class="card"><div class="card-label">Setup performance</div>${setupRows()}</section></div><section class="card" style="margin-top:12px"><div class="card-label">Most recent trades</div><table class="trade-table"><thead><tr><th>Date</th><th>Instrument</th><th>Side</th><th>Setup</th><th>Account</th><th>Size</th><th>P&amp;L</th><th>Review</th><th></th></tr></thead><tbody>${tradeRows([...state.trades].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,8))}</tbody></table></section>`}
function setupRows(){const o={};state.trades.forEach(t=>{const k=t.setup||'Unassigned';(o[k]??=[]).push(t)});const list=Object.entries(o).sort((a,b)=>sum(b[1])-sum(a[1]));return list.map(([k,ts])=>`<div class="setup-row"><strong>${esc(k)}</strong><span class="${sum(ts)>=0?'positive':'negative'}">${money(sum(ts))}</span></div><div class="progress"><i style="width:${Math.max(4,Math.min(100,stats(ts).winRate))}%"></i></div><div class="metric-note" style="margin:5px 0 13px">${ts.length} trades · ${stats(ts).winRate.toFixed(0)}% wins</div>`).join('')||'<p class="empty-note">Setups appear here once you add trades.</p>'}
function renderAccounts(){const first=state.accounts[0];if(!activeGrowthAccount||!state.accounts.some(a=>a.name===activeGrowthAccount))activeGrowthAccount=first?.name||'';return `<div class="page-heading"><div><h1>Account management</h1><p>Track account growth, set your own risk limits, and size trades from the stop distance.</p></div><div class="heading-actions"><button class="button button-primary" data-action="add-account">＋ Add account</button></div></div><div class="grid section-grid">${state.accounts.map(a=>{const ts=state.trades.filter(t=>t.account===a.name),pnl=sum(ts),equity=num(a.balance)+pnl,dailyLoss=equity*num(a.dailyLossPct)/100,targetLow=equity*num(a.monthlyTargetMinPct)/100,targetHigh=equity*num(a.monthlyTargetMaxPct)/100;return `<section class="card account-card ${activeGrowthAccount===a.name?'growth-selected':''}" data-action="select-growth-account" data-account="${esc(a.name)}" tabindex="0" aria-label="Open growth plan for ${esc(a.name)}"><div class="card-label">${esc(a.type)} <span class="pill">${esc(a.status)}</span></div><h3>${esc(a.name)}</h3><div class="account-balance">${money(equity,a.currency)}</div><div class="account-meta">Current tracked equity · start ${money(a.balance,a.currency)}</div><div class="account-lines"><span>Net P&amp;L</span><b class="${pnl>=0?'positive':'negative'}">${money(pnl,a.currency)}</b></div><div class="account-lines"><span>Trades · win rate</span><b>${ts.length} · ${stats(ts).winRate.toFixed(0)}%</b></div><div class="account-plan"><div class="account-plan-heading">Your account rules <div class="plan-actions"><button class="link-button" data-action="select-growth-account" data-account="${esc(a.name)}">View growth plan ↓</button><button class="link-button" data-action="configure-risk" data-account="${esc(a.name)}">Edit rules</button></div></div><div class="plan-value"><span>Risk per trade</span><b>${num(a.riskPct)>0?`${num(a.riskPct)}% · ${money(equity*num(a.riskPct)/100,a.currency)}`:'Not set'}</b></div><div class="plan-value"><span>Daily loss limit</span><b>${num(a.dailyLossPct)>0?`${money(dailyLoss,a.currency)} · ${num(a.dailyLossPct)}%`:'Not set'}</b></div><div class="plan-value"><span>Monthly target range</span><b>${num(a.monthlyTargetMinPct)>0||num(a.monthlyTargetMaxPct)>0?`${money(targetLow,a.currency)} – ${money(targetHigh,a.currency)}`:'Not set'}</b></div></div></section>`}).join('')}<section class="card account-card add-card" data-action="add-account"><div class="tile-icon">＋</div><h3>Add a trading account</h3><p class="metric-note">Keep evaluations, funded accounts, and personal trading organized.</p></section></div>${renderGrowthPlanner()}<section class="card risk-calculator" style="margin-top:13px"><div class="card-label">Position size calculator <span class="subtle">Uses your account risk rule and the trade’s stop</span></div>${first?`<div class="risk-form-grid"><div class="form-field"><label>Account</label><select class="field" id="risk-account">${state.accounts.map(a=>`<option value="${esc(a.name)}">${esc(a.name)} · ${money(num(a.balance)+sum(state.trades.filter(t=>t.account===a.name)),a.currency)}</option>`).join('')}</select></div><div class="form-field"><label>Stop distance (pips, ticks, or points)</label><input class="field" id="risk-distance" type="number" min="0" step="any" placeholder="e.g. 20"></div><div class="form-field"><label>Cash value per unit per lot / contract</label><input class="field" id="risk-unit-value" type="number" min="0" step="any" placeholder="Enter from broker specs"></div><div class="form-field"><label>Estimated fees per lot / contract</label><input class="field" id="risk-fees" type="number" min="0" step="any" value="0"></div><div class="form-field"><label>Broker size increment</label><input class="field" id="risk-step" type="number" min="0.000001" step="any" value="0.01"></div><div class="form-field"><label>Target in R multiples</label><input class="field" id="risk-target-r" type="number" min="0.1" step="0.1" value="2"></div></div><div class="risk-results" id="risk-results"></div><p class="import-help">Enter the pip, tick, or point value in this account’s currency from your broker’s contract specifications. Results are estimates, rounded down to your size increment; spreads, slippage, currency conversion, and changing margin can affect actual outcomes.</p>`:'<p class="empty-note">Add an account before calculating position size.</p>'}</section>`}
function growthSummary(account,plan){if(!account)return '';const steps=Math.max(1,Math.min(60,Math.floor(num(plan.steps)||30))),targetPct=Math.max(0,num(plan.targetPct)),start=num(account.balance)+sum(state.trades.filter(t=>t.account===account.name)),ending=start*Math.pow(1+targetPct/100,steps),risk=num(account.riskPct)>0?money(start*num(account.riskPct)/100,account.currency):'Not set';return `<div class="growth-summary-grid"><div><span>Starting equity</span><b>${money(start,account.currency)}</b></div><div><span>Projected after ${steps} levels</span><b>${money(ending,account.currency)}</b></div><div><span>Current risk cap per trade</span><b>${risk}</b></div></div>`}
function renderGrowthPlanner(){const account=state.accounts.find(a=>a.name===activeGrowthAccount)||state.accounts[0],plan=account?.growthPlan||{steps:30,targetPct:30,completed:[]};if(account)activeGrowthAccount=account.name;return `<section id="growth-planner" class="card growth-planner" style="margin-top:13px"><div class="card-label">Account growth plan <span class="subtle">Compounding ladder · editable scenario</span></div><div class="growth-intro"><div><h2>Plan the next ${num(plan.steps)||30} steps</h2><p>Each level starts from the prior level’s projected ending balance. Check off levels as you complete them.</p></div><div class="growth-progress"><b>${(plan.completed||[]).filter(Boolean).length} / ${num(plan.steps)||30}</b><small>levels completed</small></div></div><div class="growth-controls"><label>Account<select class="field" id="growth-account">${state.accounts.map(a=>`<option value="${esc(a.name)}" ${account?.name===a.name?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><label>Plan levels<input class="field" id="growth-steps" type="number" min="1" max="60" step="1" value="${num(plan.steps)||30}"></label><label>Profit target per level (%)<input class="field" id="growth-target" type="number" min="0.01" max="1000" step="0.1" value="${num(plan.targetPct)||30}"></label><div class="growth-rule">Per-trade risk uses the selected account’s risk rule: <b>${num(account?.riskPct)>0?`${num(account.riskPct)}%`:'not set'}</b> <button class="link-button" data-action="configure-risk" data-account="${esc(account?.name||'')}">Edit risk rule</button></div></div><div id="growth-summary">${growthSummary(account,plan)}</div><p class="growth-disclaimer">The 30% starting value mirrors the reference image; it is an example, not a recommended return. Compounding assumes every target is reached and excludes fees, slippage, withdrawals, and losing trades. It does not change actual account equity or predict results.</p><div class="growth-table-wrap"><table class="growth-table"><thead><tr><th>Level</th><th>Starting balance</th><th>Profit target</th><th>Ending balance</th><th>Risk per trade</th><th>Completed</th></tr></thead><tbody id="growth-rows">${growthRows(account,plan)}</tbody></table></div></section>`}
function growthRows(account,plan){if(!account)return '';const steps=Math.max(1,Math.min(60,Math.floor(num(plan.steps)||30))),targetPct=Math.max(0,num(plan.targetPct)),riskPct=Math.max(0,num(account.riskPct)),completed=plan.completed||[];let balance=num(account.balance)+sum(state.trades.filter(t=>t.account===account.name));return Array.from({length:steps},(_,i)=>{const target=balance*targetPct/100,end=balance+target,risk=balance*riskPct/100,row=`<tr><td>${i+1}</td><td>${money(balance,account.currency)}</td><td><b>${money(target,account.currency)}</b><small>${targetPct}%</small></td><td>${money(end,account.currency)}</td><td>${riskPct?`<b>${money(risk,account.currency)}</b><small>${riskPct}%</small>`:'<span class="subtle">Set rule</span>'}</td><td><input type="checkbox" class="toggle growth-check" data-level="${i}" ${completed[i]?'checked':''} aria-label="Mark level ${i+1} complete"></td></tr>`;balance=end;return row}).join('')}
function wireGrowthPlanner(){const select=$('#growth-account'),steps=$('#growth-steps'),target=$('#growth-target'),rows=$('#growth-rows');if(!select||!rows)return;const update=()=>{const account=state.accounts.find(a=>a.name===select.value);if(!account)return;activeGrowthAccount=account.name;account.growthPlan={...(account.growthPlan||{}),steps:Math.max(1,Math.min(60,Math.floor(num(steps.value)||30))),targetPct:Math.min(1000,Math.max(0,num(target.value))),completed:(account.growthPlan?.completed||[]).slice(0,Math.max(1,Math.min(60,Math.floor(num(steps.value)||30))))};rows.innerHTML=growthRows(account,account.growthPlan);$('.growth-intro h2').textContent=`Plan the next ${account.growthPlan.steps} steps`;$('#growth-summary').innerHTML=growthSummary(account,account.growthPlan);$('.growth-progress b').textContent=`${account.growthPlan.completed.filter(Boolean).length} / ${account.growthPlan.steps}`;$('.growth-rule b').textContent=num(account.riskPct)>0?`${num(account.riskPct)}%`:'not set';const edit=$('.growth-rule [data-account]');if(edit)edit.dataset.account=account.name;save()};[steps,target].forEach(el=>el.addEventListener('input',update));select.addEventListener('change',()=>{const account=state.accounts.find(a=>a.name===select.value),plan=account?.growthPlan||{steps:30,targetPct:30,completed:[]};if(steps)steps.value=num(plan.steps)||30;if(target)target.value=num(plan.targetPct)||30;update()});rows.addEventListener('change',e=>{const box=e.target.closest('.growth-check');if(!box)return;const account=state.accounts.find(a=>a.name===select.value);if(!account)return;const plan=account.growthPlan||{steps:30,targetPct:30,completed:[]};plan.completed=Array.from({length:plan.steps},(_,i)=>i===Number(box.dataset.level)?box.checked:!!plan.completed[i]);account.growthPlan=plan;save();$('.growth-progress b').textContent=`${plan.completed.filter(Boolean).length} / ${plan.steps}`})}
function wireRiskCalculator(){const ids=['risk-account','risk-distance','risk-unit-value','risk-fees','risk-step','risk-target-r'];ids.forEach(id=>$('#'+id)?.addEventListener('input',updateRiskEstimate));$('#risk-account')?.addEventListener('change',updateRiskEstimate);updateRiskEstimate()}
function updateRiskEstimate(){const root=$('#risk-results');if(!root)return;const account=state.accounts.find(a=>a.name===$('#risk-account')?.value),distance=num($('#risk-distance')?.value),value=num($('#risk-unit-value')?.value),fees=num($('#risk-fees')?.value),step=num($('#risk-step')?.value),targetR=num($('#risk-target-r')?.value),equity=account?num(account.balance)+sum(state.trades.filter(t=>t.account===account.name)):0,riskPct=num(account?.riskPct),dailyPct=num(account?.dailyLossPct),riskBudget=equity*riskPct/100,dailyLimit=equity*dailyPct/100,todayPnl=account?sum(state.trades.filter(t=>t.account===account.name&&t.date===isoDay(new Date()))):0,used=Math.max(0,-todayPnl),perUnitRisk=distance*value+fees,raw=perUnitRisk>0?riskBudget/perUnitRisk:0,qty=step>0?Math.floor((raw+1e-10)/step)*step:0,precision=step>0?Math.min(8,(String(step).split('.')[1]||'').length):2,plannedRisk=qty*perUnitRisk;let message='Enter a stop distance and the broker’s cash value per pip, tick, or point.';if(!riskPct)message='Set a risk per trade in this account’s rules to calculate size.';else if(distance>0&&value>0&&step>0){message=qty>0?`Suggested maximum: ${qty.toFixed(precision)} lots / contracts / units`:'Risk budget is smaller than the minimum size increment.'}const targetProfit=plannedRisk*Math.max(0,targetR);root.innerHTML=`<div class="risk-result-primary"><span>Risk budget · ${riskPct?`${riskPct}% of ${money(equity,account?.currency)}`:'risk rule not set'}</span><strong>${riskPct?money(riskBudget,account?.currency):'—'}</strong></div><div class="risk-result-grid"><div><span>Risk at stop for suggested size</span><b>${qty?money(plannedRisk,account?.currency):'—'}</b></div><div><span>Scenario at ${targetR||0}R target</span><b class="positive">${qty?money(targetProfit,account?.currency):'—'}</b></div><div><span>Today’s realized P&amp;L</span><b class="${todayPnl>=0?'positive':'negative'}">${money(todayPnl,account?.currency)}</b></div><div><span>Daily loss limit · remaining</span><b>${dailyPct?`${money(dailyLimit,account?.currency)} · ${money(Math.max(0,dailyLimit-used),account?.currency)}`:'Not set'}</b></div></div><p class="risk-message ${riskPct&&distance>0&&value>0&&step>0?'':'warning'}">${esc(message)}${dailyPct&&used>=dailyLimit&&dailyLimit>0?' · Daily loss limit reached based on recorded trades.':''}</p>`}
function renderSetups(){const o={};[...(state.setups||[]),...state.trades.map(t=>t.setup||'Unassigned')].forEach(k=>o[k]=state.trades.filter(t=>(t.setup||'Unassigned')===k));return `<div class="page-heading"><div><h1>Setups</h1><p>Compare the playbooks behind your trading results.</p></div><div class="heading-actions"><button class="button button-primary" data-action="add-setup">＋ New setup</button></div></div><div class="grid section-grid">${Object.entries(o).sort((a,b)=>sum(b[1])-sum(a[1])).map(([name,ts])=>`<section class="card setup-card-full"><div class="card-label">Trading setup</div><h3>${esc(name)}</h3><div class="metric-big ${sum(ts)>=0?'positive':'negative'}">${money(sum(ts))}</div><div class="metric-note">Net profit &amp; loss</div><div class="setup-stats"><div>Trades<b>${ts.length}</b></div><div>Win rate<b>${stats(ts).winRate.toFixed(0)}%</b></div><div>Avg. trade<b>${money(stats(ts).avg)}</b></div></div><div class="progress"><i style="width:${Math.max(4,Math.min(100,stats(ts).winRate))}%"></i></div></section>`).join('')}<section class="card setup-card-full" data-action="add-setup" style="cursor:pointer;display:grid;place-content:center;text-align:center"><div class="tile-icon">＋</div><h3>Create setup</h3></section></div>`}
function renderReviews(){const pending=state.trades.filter(t=>!t.reviewed).sort((a,b)=>b.date.localeCompare(a.date));return `<div class="page-heading"><div><h1>Reviews</h1><p>Build consistency with daily, weekly, and trade reviews.</p></div><div class="heading-actions"><button class="button button-primary" data-action="new-review">＋ New review</button></div></div><div class="grid review-cards"><section class="card review-tile" data-action="review-daily"><div class="tile-icon">▣</div><h3>Daily review</h3><p>Capture what went well and what to improve.</p><div class="review-link">Start today’s review →</div></section><section class="card review-tile" data-action="review-weekly"><div class="tile-icon">▦</div><h3>Weekly review</h3><p>Reflect on patterns across your trading week.</p><div class="review-link">Create weekly review →</div></section><section class="card review-tile" data-action="review-monthly"><div class="tile-icon">▤</div><h3>Monthly review</h3><p>Check progress against the bigger picture.</p><div class="review-link">Create monthly review →</div></section></div><section class="card table-card" style="margin-top:13px"><div class="table-toolbar"><h3>Trades needing review <span class="subtle">${pending.length}</span></h3><button class="button" data-action="review-all">Mark all reviewed</button></div><table class="trade-table"><thead><tr><th>Date</th><th>Instrument</th><th>Side</th><th>Setup</th><th>Account</th><th>Size</th><th>P&amp;L</th><th>Review</th><th></th></tr></thead><tbody>${tradeRows(pending)}</tbody></table></section>${state.reviews.length?`<section class="card" style="margin-top:13px"><div class="card-label">Saved reflections</div>${state.reviews.map(r=>`<div class="settings-row"><span><b>${esc(r.title)}</b><small>${dateFmt(r.date)} · ${esc(r.type)}</small></span><span>${esc(r.text.slice(0,110))}</span></div>`).join('')}</section>`:''}`}
function renderCalendar(){const now=new Date(),yr=now.getFullYear(),mo=now.getMonth(),first=new Date(yr,mo,1).getDay(),days=new Date(yr,mo+1,0).getDate();let cells=Array.from({length:first},()=>'<div></div>').join('');for(let d=1;d<=days;d++){const iso=isoDay(new Date(yr,mo,d)),p=sum(state.trades.filter(t=>t.date===iso));cells+=`<div class="calendar-day ${iso===isoDay(now)?'today':''} ${p<0?'loss':''}">${d}${p!==0?`<span class="day-pnl">${p>0?'+':''}${money(p)}</span>`:''}</div>`}return `<div class="page-heading"><div><h1>Calendar</h1><p>Daily trading activity and realized results.</p></div></div><div class="calendar-layout"><section class="card"><div class="card-label">${new Intl.DateTimeFormat(undefined,{month:'long',year:'numeric'}).format(now)}</div><div class="calendar-grid">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>`<span>${x}</span>`).join('')}${cells}</div></section><section class="card"><div class="card-label">Month summary</div><div class="metric-big">${money(sum(state.trades.filter(t=>t.date.slice(0,7)===`${yr}-${String(mo+1).padStart(2,'0')}`)))}</div><div class="metric-note">Net P&amp;L this month</div><div style="margin-top:22px">${setupRows()}</div></section></div>`}
function renderSession(){return `<div class="page-heading"><div><h1>Session Mode</h1><p>Use a focused session to plan, execute, and reflect.</p></div></div><div class="session-layout"><section class="card session-clock"><div class="card-label">Focus timer</div><div class="clock" id="clock-display">25:00</div><div class="metric-note">Take a moment to plan before placing a trade.</div><div class="session-controls"><button class="button button-primary" id="timer-toggle">Start session</button><button class="button" id="timer-reset">Reset</button></div></section><div class="grid session-prompts" style="margin-top:12px"><section class="card"><div class="card-label">Pre-session plan</div><textarea class="field" id="plan-note" placeholder="What is your plan for today?"></textarea><button class="button" style="margin-top:10px" data-action="save-plan">Save plan</button></section><section class="card"><div class="card-label">Session checklist</div><label class="settings-row"><span>Know the key levels</span><input type="checkbox" class="toggle"></label><label class="settings-row"><span>Set risk limits</span><input type="checkbox" class="toggle"></label><label class="settings-row"><span>Review the plan first</span><input type="checkbox" class="toggle"></label></section></div></div>`}
function renderImport(){return `<div class="page-heading"><div><h1>Import trades</h1><p>Bring trades into this browser workspace from a CSV file.</p></div></div><section class="card" style="max-width:800px;margin:0 auto"><div class="card-label">CSV trade import</div><label class="import-zone" for="csv-file"><strong>Choose a CSV file or drop it here</strong>We’ll look for common columns such as date, symbol, side, setup, account, size, and P&amp;L.<input id="csv-inline" type="file" accept=".csv,text/csv" hidden></label><p class="import-help">The import preview maps familiar column names automatically. Import creates trades in this browser only. For broker specific statement parsing, the original Obsidian plugin’s server powered import is not included in this browser edition.</p><div id="import-preview"></div></section>`}
function renderSettings(){return `<div class="page-heading"><div><h1>Settings &amp; data</h1><p>Customize this browser workspace and manage your journal data.</p></div></div><section class="card" style="max-width:800px"><div class="card-label">Workspace</div><div class="settings-row"><span>Display name<small>Shown on the home dashboard</small></span><input class="field" id="setting-name" value="${esc(state.settings.name)}"></div><div class="settings-row"><span>Monthly P&amp;L goal<small>Used by the home dashboard progress card</small></span><input class="field" id="setting-goal" type="number" value="${num(state.settings.goal)}"></div><div class="settings-row"><span>Currency<small>Currency used for displaying results</small></span><select class="select-control" id="setting-currency">${['USD','EUR','GBP','CAD','AUD','JPY','GHS'].map(c=>`<option ${state.settings.currency===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="settings-row"><span><b>Export journal data</b><small>Download all trades, accounts, reviews, and settings as a JSON backup.</small></span><button class="button" data-action="export">⇩ Export backup</button></div><div class="settings-row"><span><b>Restore a backup</b><small>Replace current browser data from a Journalit JSON backup.</small></span><label class="button" for="backup-file">Choose backup<input hidden type="file" id="backup-file" accept="application/json"></label></div><div class="settings-row"><span><b>Reset demo workspace</b><small>Restore the sample Journalit workspace on this device.</small></span><button class="button" data-action="reset-demo">Reset demo data</button></div></section>`}
function render(){if(!pageNames[page])page='home';$('#top-title').textContent=pageNames[page];$('#today-label').textContent=new Intl.DateTimeFormat(undefined,{weekday:'short',month:'short',day:'numeric'}).format(new Date());$('#auth-button').textContent=JournalitCloud.enabled()?'Google sync':'Connect Google';if($('#connection-status'))$('#connection-status').textContent=navigator.onLine?'Online · saved on this device':'Offline · saved on this device';$$('.nav-item[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const views={home:dashboardHome,trades:renderTrades,dashboard:renderDashboard,accounts:renderAccounts,setups:renderSetups,reviews:renderReviews,calendar:renderCalendar,session:renderSession,import:renderImport,settings:renderSettings};$('#page-root').innerHTML=views[page]();if(page==='settings')$('#page-root').insertAdjacentHTML('afterbegin',`<section class="card" style="margin-bottom:13px"><div class="card-label">Google Drive sync</div><p class="import-help">${window.JournalitCloud?.configured()?'Your journal saves to this device immediately and can sync to a private spreadsheet in your Google Drive. Connect while online once; edits made offline will wait and sync when you reconnect.':'To enable Google sync, deploy the Apps Script files in the apps-script folder as a web app, then paste its /exec URL into web/apps-script-config.js.'}</p><div class="settings-row"><span><b>${JournalitCloud.enabled()?'Connected to Google Drive':'Google account'}</b><small>${JournalitCloud.enabled()?'Google Drive sync is enabled. Offline changes are saved here and queued.':JournalitCloud.configured()?'Connect Google to create or load your private Drive journal.':'Deploy Apps Script and add its URL to enable sync.'}</small></span><span>${JournalitCloud.enabled()?'<button class="button" data-action="cloud-upload">Upload this device</button> <button class="button" data-action="cloud-signout">Disconnect</button>':'<button class="button" data-action="auth">Connect Google</button>'}</span></div></section>`);if(page==='accounts'){wireGrowthPlanner();wireRiskCalculator();}if(page==='trades'){const refresh=()=>{const body=$('.trade-table tbody'),status=$('#review-filter')?.value||'all';if(body)body.innerHTML=tradeRows(filteredTrades().filter(t=>status==='all'||(status==='reviewed'?t.reviewed:!t.reviewed)))};$('#trade-search')?.addEventListener('input',e=>{filterText=e.target.value;refresh()});$('#review-filter')?.addEventListener('change',refresh)}if(page==='settings'){[['setting-name','name'],['setting-goal','goal'],['setting-currency','currency']].forEach(([id,key])=>$('#'+id)?.addEventListener('change',e=>{state.settings[key]=key==='goal'?num(e.target.value):e.target.value;save();if(key==='name')render()}));$('#backup-file')?.addEventListener('change',restoreBackup)}if(page==='import')wireImport();if(page==='session')wireTimer();history.replaceState(null,'',`#${page}`)}
function go(p){page=p;filterText='';$('#sidebar').classList.remove('open');render();window.scrollTo(0,0)}
function toast(message){const old=$('.toast');old?.remove();const t=document.createElement('div');t.className='toast';t.textContent=message;document.body.append(t);setTimeout(()=>t.remove(),2800)}
function openModal(title,body,submitLabel='Save',onSubmit=()=>{}){$('#modal-root').innerHTML=`<div class="modal-backdrop"><form class="modal"><div class="modal-header"><h2>${title}</h2><button type="button" class="modal-close" aria-label="Close">×</button></div><div class="modal-body">${body}</div><div class="modal-footer"><span class="metric-note">Changes are saved in this browser.</span><button class="button button-primary" type="submit">${submitLabel}</button></div></form></div>`;const root=$('#modal-root'),form=$('form',root);$('.modal-close',root).onclick=()=>root.innerHTML='';$('.modal-backdrop',root).onclick=e=>{if(e.target===e.currentTarget)root.innerHTML=''};form.onsubmit=async e=>{e.preventDefault();try{const result=onSubmit(new FormData(form));if(result&&typeof result.then==='function'){form.querySelector('[type=submit]').disabled=true;const close=await result;if(close!==false)root.innerHTML=''}else if(result!==false)root.innerHTML=''}catch(err){toast(err.message||'Something went wrong');form.querySelector('[type=submit]').disabled=false}}}
function tradeForm(){const today=isoDay(new Date()),setups=[...new Set(state.trades.map(t=>t.setup).filter(Boolean))],accounts=state.accounts.map(a=>a.name);openModal('Add trade',`<div class="form-grid"><div class="form-field"><label>Instrument</label><input name="instrument" class="field" placeholder="e.g. EURUSD" required></div><div class="form-field"><label>Direction</label><select name="direction" class="field"><option>Long</option><option>Short</option></select></div><div class="form-field"><label>Trade date</label><input name="date" class="field" type="date" value="${today}" required></div><div class="form-field"><label>Asset type</label><select name="assetType" class="field"><option>Forex</option><option>Futures</option><option>Stocks</option><option>Crypto</option><option>Options</option><option>CFD</option></select></div><div class="form-field"><label>Setup</label><input name="setup" class="field" list="setup-list" placeholder="Choose or create"><datalist id="setup-list">${setups.map(s=>`<option>${esc(s)}</option>`).join('')}</datalist></div><div class="form-field"><label>Account</label><select name="account" class="field">${accounts.map(s=>`<option>${esc(s)}</option>`).join('')}</select></div><div class="form-field"><label>Position size</label><input name="size" class="field" type="number" step="any" value="1"></div><div class="form-field"><label>Net P&amp;L</label><input name="pnl" class="field" type="number" step="any" placeholder="0.00" required></div><div class="form-field wide"><label>Trade notes</label><textarea name="notes" class="field" placeholder="Thesis, execution, and lessons learned"></textarea></div></div>`,`Save trade`,d=>{state.trades.push({id:crypto.randomUUID(),date:d.get('date'),instrument:String(d.get('instrument')).toUpperCase(),direction:d.get('direction'),assetType:d.get('assetType'),setup:d.get('setup')||'Unassigned',account:d.get('account'),size:num(d.get('size')),pnl:num(d.get('pnl')),notes:d.get('notes')||'',reviewed:false,tags:[]});save();render();toast('Trade added to your journal')})}
function addAccount(){openModal('Add account',`<div class="form-grid"><div class="form-field"><label>Account name</label><input class="field" name="name" required placeholder="e.g. My Trading Account"></div><div class="form-field"><label>Account type</label><select class="field" name="type"><option>Personal</option><option>Prop evaluation</option><option>Funded account</option><option>Broker</option></select></div><div class="form-field"><label>Starting balance</label><input class="field" name="balance" type="number" step="any" value="0"></div><div class="form-field"><label>Currency</label><select class="field" name="currency">${['USD','EUR','GBP','CAD','AUD','JPY','GHS'].map(c=>`<option>${c}</option>`)}</select></div></div>`,`Add account`,d=>{const name=String(d.get('name')).trim();if(state.accounts.some(a=>a.name.toLowerCase()===name.toLowerCase())){toast('An account with that name already exists');return false}state.accounts.push({name,type:d.get('type'),balance:num(d.get('balance')),currency:d.get('currency'),status:'Active',riskPct:null,dailyLossPct:null,monthlyTargetMinPct:null,monthlyTargetMaxPct:null});save();render();toast('Account added')})}
function configureRisk(accountName){const a=state.accounts.find(x=>x.name===accountName);if(!a)return;openModal(`Risk rules · ${esc(a.name)}`,`<p class="metric-note" style="margin:0 0 16px">Set the limits you want this workspace to use. These are your rules, not a suggested trading strategy.</p><div class="form-grid"><div class="form-field"><label>Maximum risk per trade (% of equity)</label><input class="field" name="riskPct" type="number" min="0.01" max="100" step="0.01" value="${a.riskPct??''}" required></div><div class="form-field"><label>Maximum daily loss (% of equity)</label><input class="field" name="dailyLossPct" type="number" min="0.01" max="100" step="0.01" value="${a.dailyLossPct??''}" required></div><div class="form-field"><label>Monthly target range · lower (%)</label><input class="field" name="targetMin" type="number" min="0" max="1000" step="0.1" value="${a.monthlyTargetMinPct??''}" required></div><div class="form-field"><label>Monthly target range · upper (%)</label><input class="field" name="targetMax" type="number" min="0" max="1000" step="0.1" value="${a.monthlyTargetMaxPct??''}" required></div></div>`,`Save rules`,d=>{const risk=num(d.get('riskPct')),daily=num(d.get('dailyLossPct')),low=num(d.get('targetMin')),high=num(d.get('targetMax'));if(risk<=0||daily<=0||low<0||high<low){toast('Enter positive risk limits and a target range where the upper value is at least the lower value');return false}Object.assign(a,{riskPct:risk,dailyLossPct:daily,monthlyTargetMinPct:low,monthlyTargetMaxPct:high});save();render();toast('Account rules saved')})}
function saveReview(type){openModal(`${type} review`,`<div class="form-grid"><div class="form-field wide"><label>Review title</label><input class="field" name="title" value="${type} review · ${dateFmt(isoDay(new Date()))}" required></div><div class="form-field wide"><label>What went well?</label><textarea class="field" name="wentWell" placeholder="Wins, good decisions, and habits worth repeating"></textarea></div><div class="form-field wide"><label>What can improve?</label><textarea class="field" name="improve" placeholder="Mistakes, missed opportunities, and lessons"></textarea></div><div class="form-field wide"><label>Plan for next session</label><textarea class="field" name="plan" placeholder="One or two concrete commitments"></textarea></div></div>`,`Save review`,d=>{state.reviews.unshift({id:crypto.randomUUID(),type,title:d.get('title'),date:isoDay(new Date()),text:[d.get('wentWell'),d.get('improve'),d.get('plan')].filter(Boolean).join(' · ')});save();render();toast('Review saved')})}
function download(name,content,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportBackup(){download(`journalit-backup-${isoDay(new Date())}.json`,JSON.stringify(state,null,2),'application/json');toast('Journal backup exported')}
function restoreBackup(e){const f=e.target.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const x=JSON.parse(r.result);if(!Array.isArray(x.trades)||!Array.isArray(x.accounts))throw 0;state=x;save();render();toast('Journal backup restored')}catch{toast('This file is not a valid Journalit backup')}};r.readAsText(f)}
function parseCSV(text){const rows=[];let row=[],val='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted&&c==='"'&&text[i+1]==='"'){val+='"';i++}else if(c==='"')quoted=!quoted;else if(c===','&&!quoted){row.push(val.trim());val=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(val.trim());if(row.some(Boolean))rows.push(row);row=[];val=''}else val+=c}row.push(val.trim());if(row.some(Boolean))rows.push(row);return rows}
function wireImport(){const picker=$('#csv-file'),inline=$('#csv-inline');const process=async f=>{if(!f)return;const rows=parseCSV(await f.text());if(rows.length<2){toast('The CSV has no trade rows');return}const h=rows[0].map(x=>x.toLowerCase().replace(/[^a-z0-9]/g,''));const col=(...names)=>names.map(n=>h.indexOf(n)).find(i=>i>=0);const date=col('date','tradedate','entrydate','opentime'),sym=col('symbol','instrument','ticker','asset'),side=col('side','direction','type'),setup=col('setup','strategy'),account=col('account','accountname'),size=col('size','quantity','qty','lots'),pnl=col('pnl','netpnl','profit','netprofit','realizedpnl');const found=rows.slice(1).map(r=>({date:r[date]||isoDay(new Date()),instrument:r[sym]||'',direction:/short|sell/i.test(r[side]||'')?'Short':'Long',setup:r[setup]||'Imported',account:r[account]||state.accounts[0]?.name||'Personal',size:num(r[size]||1),pnl:num((r[pnl]||'0').replace(/[,$]/g,'')),assetType:'Other',reviewed:false,tags:[]})).filter(t=>t.instrument);const preview=$('#import-preview');if(!found.length){preview.innerHTML='<p class="negative">Could not identify trade symbols. Use columns like date, symbol, side, setup, account, size, and pnl.</p>';return}preview.innerHTML=`<div style="margin-top:20px"><div class="card-label">Import preview <span>${found.length} trades detected</span></div><div class="table-card"><table class="trade-table"><thead><tr><th>Date</th><th>Instrument</th><th>Side</th><th>Setup</th><th>Account</th><th>Size</th><th>P&amp;L</th></tr></thead><tbody>${tradeRows(found.slice(0,5).map((t,i)=>({...t,id:`preview-${i}`})))}</tbody></table></div><button class="button button-primary" style="margin-top:14px" id="confirm-import">Import ${found.length} trades</button></div>`;$('#confirm-import').onclick=()=>{state.trades.push(...found.map(t=>({...t,id:crypto.randomUUID()})));const missing=[...new Set(found.map(t=>t.account).filter(a=>!state.accounts.some(x=>x.name===a)))];missing.forEach(name=>state.accounts.push({name,type:'Imported',balance:0,currency:state.settings.currency,status:'Active'}));save();toast(`${found.length} trades imported`);go('trades')}};[picker,inline].forEach(i=>i?.addEventListener('change',()=>process(i.files[0])));const zone=$('.import-zone');zone?.addEventListener('dragover',e=>{e.preventDefault();zone.style.borderColor='var(--green)'});zone?.addEventListener('dragleave',()=>zone.style.borderColor='');zone?.addEventListener('drop',e=>{e.preventDefault();process(e.dataTransfer.files[0])})}
function wireTimer(){const display=$('#clock-display'),toggle=$('#timer-toggle');if(!display||!toggle)return;const update=()=>display.textContent=`${String(Math.floor(sessionSeconds/60)).padStart(2,'0')}:${String(sessionSeconds%60).padStart(2,'0')}`;toggle.onclick=()=>{if(sessionInterval){clearInterval(sessionInterval);sessionInterval=null;toggle.textContent='Resume session'}else{toggle.textContent='Pause session';sessionInterval=setInterval(()=>{sessionSeconds=Math.max(0,sessionSeconds-1);update();if(!sessionSeconds){clearInterval(sessionInterval);sessionInterval=null;toggle.textContent='Start session';toast('Focus session complete')}} ,1000)}};$('#timer-reset').onclick=()=>{clearInterval(sessionInterval);sessionInterval=null;sessionSeconds=25*60;toggle.textContent='Start session';update()};$('#plan-note').value=localStorage.getItem('journalit-plan')||''}
async function cloudAuth(){if(!JournalitCloud.configured()){toast('Add your Apps Script /exec URL in web/apps-script-config.js first');go('settings');return}try{const result=await JournalitCloud.connect();if(result?.payload){if(confirm('A Google Drive journal exists. Load it on this device? Your current local journal will be kept as a safety copy.')){localStorage.setItem('journalit-local-before-cloud',localStorage.getItem(STORE_KEY)||'');state=result.payload;localStorage.setItem(STORE_KEY,JSON.stringify(state));toast('Google Drive journal loaded')}else{JournalitCloud.disconnect();toast('Kept this device journal; Google sync was not enabled')}}else if(confirm('No Google Drive journal was found. Upload this device journal to a private spreadsheet in your Google Drive?')){await JournalitCloud.upload(state);toast('Journal saved to your Google Drive')}else{JournalitCloud.disconnect();toast('Kept this journal on this device only')}render()}catch(err){toast(err.message||'Could not connect to Google.')}}
async function uploadLocalJournal(){if(!JournalitCloud.enabled())return;if(!confirm('Upload this device journal to your Google Drive workspace? This replaces the connected Google copy.'))return;try{await JournalitCloud.upload(state);toast('Journal uploaded to Google Drive');render()}catch(err){toast('Upload failed: '+err.message)}}
function updateConnectionStatus(){const el=$('#connection-status');if(el)el.textContent=navigator.onLine?'Online · saved on this device':'Offline · saved on this device';const button=$('#auth-button');if(button)button.textContent=JournalitCloud.enabled()?'Google sync':'Connect Google'}
async function restoreGoogleWorkspace(){if(!JournalitCloud.enabled()||!navigator.onLine)return;try{const result=await JournalitCloud.load();if(result.hasCloud&&result.payload){if(localStorage.getItem('journalit-google-sync-pending')==='yes'){await JournalitCloud.upload(state)}else{state=result.payload;localStorage.setItem(STORE_KEY,JSON.stringify(state));render()}}}catch(err){toast('Google sync is waiting: '+err.message)}}
window.addEventListener('online',()=>{updateConnectionStatus();JournalitCloud.syncPending(()=>state,err=>toast('Sync waiting: '+err.message))});window.addEventListener('offline',updateConnectionStatus);updateConnectionStatus();if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js').catch(()=>{}));restoreGoogleWorkspace();
document.addEventListener('click',e=>{const nav=e.target.closest('[data-page]');if(nav){go(nav.dataset.page);return}const a=e.target.closest('[data-action]');if(a){switch(a.dataset.action){case'auth':cloudAuth();break;case'cloud-upload':uploadLocalJournal();break;case'cloud-signout':if(confirm('Disconnect Google sync? Your journal stays on this device.')){JournalitCloud.disconnect();render();updateConnectionStatus();toast('Google sync disconnected')}break;case'add-trade':tradeForm();break;case'add-account':addAccount();break;case'select-growth-account':activeGrowthAccount=a.dataset.account;render();$('#growth-planner')?.scrollIntoView({behavior:'smooth',block:'start'});break;case'configure-risk':configureRisk(a.dataset.account);break;case'add-setup':openModal('New setup','<div class="form-field"><label>Setup name</label><input class="field" name="name" required placeholder="e.g. Trend continuation"></div>','Create setup',d=>{const name=String(d.get('name')).trim();if(name&&!state.setups.includes(name))state.setups.push(name);save();go('setups');toast('Setup created')});break;case'export':exportBackup();break;case'settings':go('settings');break;case'go':go(a.dataset.page);break;case'toggle-review':{const t=state.trades.find(x=>x.id===a.dataset.id);if(t){t.reviewed=!t.reviewed;save();render()}break}case'review-all':state.trades.forEach(t=>t.reviewed=true);save();render();toast('All trades marked reviewed');break;case'new-review':case'review-daily':saveReview('Daily');break;case'review-weekly':saveReview('Weekly');break;case'review-monthly':saveReview('Monthly');break;case'reset-demo':if(confirm('Replace this browser journal with the sample workspace?')){state=loadState();localStorage.setItem(STORE_KEY,JSON.stringify(state));render();toast('Sample workspace restored')}break;case'save-plan':localStorage.setItem('journalit-plan',$('#plan-note')?.value||'');toast('Session plan saved');break}}const tr=e.target.closest('[data-trade]');if(tr&&page==='home'){const t=state.trades.find(x=>x.id===tr.dataset.trade);if(t)openModal(`${esc(t.instrument)} trade`,`<div class="settings-row"><span>Date</span><b>${dateFmt(t.date)}</b></div><div class="settings-row"><span>Direction · Setup</span><b>${esc(t.direction)} · ${esc(t.setup)}</b></div><div class="settings-row"><span>Net P&amp;L</span><b class="${t.pnl>=0?'positive':'negative'}">${money(t.pnl)}</b></div><p>${esc(t.notes||'No notes added.')}</p>`,'Close',()=>{})}});
$('#main-nav').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b)go(b.dataset.page)});$('#mobile-menu').onclick=()=>$('#sidebar').classList.toggle('open');$('#global-search').addEventListener('keydown',e=>{if(e.key==='Enter'){filterText=e.currentTarget.value;go('trades');filterText=e.currentTarget.value;const f=$('#trade-search');if(f){f.value=filterText;f.dispatchEvent(new Event('input'))}}});document.addEventListener('keydown',e=>{if(e.target.matches?.('.account-card[data-account]')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();activeGrowthAccount=e.target.dataset.account;render();$('#growth-planner')?.scrollIntoView({behavior:'smooth',block:'start'})}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#global-search').focus()}if(e.key==='Escape')$('#modal-root').innerHTML=''});render();
